import{_ as a,a as t}from"./chunks/02c-search-content.8lrBO6Dd.js";import{_ as o,o as n,c as r,a0 as s}from"./chunks/framework.DVzt4Sxt.js";const g=JSON.parse('{"title":"Workspace search","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/search.md","filePath":"en/features/search.md","lastUpdated":1791396169000}'),i={name:"en/features/search.md"};function l(c,e,h,d,p,m){return n(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="workspace-search" tabindex="-1">Workspace search <a class="header-anchor" href="#workspace-search" aria-label="Permalink to &quot;Workspace search&quot;">​</a></h1><p>Sidebar <strong>Search</strong> opens a floating panel (desktop) or bottom sheet (phone) and <strong>does not replace</strong> the main view. Search by filename, or regex over file contents.</p><p><img src="'+a+'" alt="Filename search: REWIND → 5 hits"></p><h2 id="filename-search-find" tabindex="-1">Filename search (Find) <a class="header-anchor" href="#filename-search-find" aria-label="Permalink to &quot;Filename search (Find)&quot;">​</a></h2><ol><li>Open Search, mode <strong>Files</strong>.</li><li>Choose root and subpath (<code>/</code> means the whole root).</li><li>Enter a name fragment (e.g. <code>REWIND</code>), click <strong>Search</strong>.</li><li>Results show hits / scanned; you can Filter results further.</li><li>Preview with the eye icon, or open the file’s location.</li></ol><h2 id="content-search-content" tabindex="-1">Content search (Content) <a class="header-anchor" href="#content-search-content" aria-label="Permalink to &quot;Content search (Content)&quot;">​</a></h2><p>Switch mode to <strong>Content</strong> and enter a regex (e.g. <code>TODO|FIXME</code>). Hits show path, line number, and context with matches highlighted.</p><p><img src="'+t+'" alt="Content search TODO|FIXME"></p><h2 id="options-optional" tabindex="-1">Options (optional) <a class="header-anchor" href="#options-optional" aria-label="Permalink to &quot;Options (optional)&quot;">​</a></h2><p>Expand Options to set:</p><ul><li>Extension filters (comma / space separated, not globs)</li><li>Context line count (Content mode)</li><li>Max depth</li><li>Ignored directory names (e.g. <code>node_modules</code>, <code>venv</code>, <code>renv</code>)</li></ul><h2 id="how-search-behaves" tabindex="-1">How search behaves <a class="header-anchor" href="#how-search-behaves" aria-label="Permalink to &quot;How search behaves&quot;">​</a></h2><ul><li>One search at a time per Agent; you can <strong>Cancel</strong> anytime.</li><li>For large trees, narrow the path, add ignores, and limit depth.</li><li>Progress streams over SSE; closing the panel does not force-kill a running request (use Cancel).</li><li>Search uses the Agent&#39;s <code>workspace_search</code> capability (on by default in current releases).</li></ul><p>Related: <a href="./browse">Browse files</a> · <a href="./collections">Collections</a></p>',14)])])}const _=o(i,[["render",l]]);export{g as __pageData,_ as default};
